		tsauth.EnvPublicOrigin: tsauth.PublicOrigin("gru"), tsauth.EnvAPIURL: tsauth.APIURL("gru"), tsauth.EnvDatabase: tsauth.Database,
		tsauth.EnvAudiences: tsauth.APIURL("gru"), tsauth.EnvDashboardRedirectURIs: tsauth.DashboardRedirectURI,
		tsauth.EnvDashboardLogoutURIs: tsauth.DashboardLogoutURI}, Secrets: secrets}
}

// tsAuthTestAgent is an agent whose ts-auth root belongs to the test's own
// user, standing in for the workload user.
func tsAuthTestAgent(t *testing.T) *Agent {
	t.Helper()
	root := filepath.Join(traversableTempDir(t), "ts-auth")
	identity := WorkloadIdentity{UID: uint32(os.Getuid()), GID: uint32(os.Getgid())}
	return &Agent{terraBase: map[string]terraBaseMember{}, cfg: AgentConfig{TSAuthRoot: root, WorkloadIdentity: identity,
		InstallRoot: "/var/lib/host/install", StateRoot: "/var/lib/host/state"}}
}

func traversableTempDir(t *testing.T) string {
	t.Helper()
	dir, err := os.MkdirTemp("/tmp", "ts-terrabase-root-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.RemoveAll(dir) })
	if err := os.Chmod(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	return dir
}

func (a *Agent) prepareTSAuth(d Desired, secrets map[string]string) (map[string]string, error) {
	if err := tsauth.ValidateProfile(d.Cell, d.Args, d.Env, d.Secrets); err != nil {
		return nil, err
	}
	if err := tsauth.ValidateSecrets(secrets); err != nil {
		return nil, err
	}
	root, identity := a.cfg.TSAuthRoot, a.cfg.WorkloadIdentity
	// Recheck the ancestors right before the privileged effects below.
	if err := validateWorkloadRoot("ts-auth", root, identity, a.cfg.InstallRoot, a.cfg.StateRoot, a.cfg.TerraBaseRoot); err != nil {
		return nil, err
	}
	layout := tsauth.Layout(root)
	if err := ensureOwnedDir(root, os.Geteuid(), int(identity.GID), 0o750); err != nil {
		return nil, err
	}
	if err := ensureOwnedDir(layout.Bundle(), int(identity.UID), int(identity.GID), 0o700); err != nil {
		return nil, err
	}
	return layout.Env(d.Env, secrets, a.tsAuthPort()), nil
}

func validateWorkloadRoot(name, root string, identity WorkloadIdentity, others ...string) error {
	separator := string(filepath.Separator)
	for _, other := range others {
		if other != "" && (root == other || strings.HasPrefix(root, other+separator) || strings.HasPrefix(other, root+separator)) {
			return errors.New(name + " root must be separate from the install, state and other workload roots")
		}
	}
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == separator {
		return errors.New(name + " root must be a clean absolute path other than /")
	}
	// Only the workload root may be absent; every parent must already be safe.
	if err := inspectWorkloadPath(filepath.Dir(root), identity, true, false, false); err != nil {
		return fmt.Errorf("%s root parent: %w", name, err)
	}
	// Every existing component is a real, non-replaceable directory...
	if err := inspectWorkloadPath(root, identity, true, true, false); err != nil {
		return fmt.Errorf("%s root: %w", name, err)
	}
	// ...and the workload cannot create the root before the agent does, not
	// even in a sticky parent such as /tmp.
	if info, err := os.Lstat(filepath.Dir(root)); err == nil && identity.UID != uint32(os.Geteuid()) {
		owner, _ := info.Sys().(*syscall.Stat_t)
		write := info.Mode().Perm() & 0o002
		if owner != nil && owner.Gid == identity.GID {
			write = info.Mode().Perm() & 0o020
		}
		if owner != nil && owner.Uid == identity.UID {
			write = info.Mode().Perm() & 0o200
		}
		if write != 0 {
			return errors.New("the workload identity can create entries next to the " + name + " root")
		}
	}
	// ...so the path resolves to itself.
	existing := root
	for {
		if _, err := os.Lstat(existing); err == nil {
			break
		}
		existing = filepath.Dir(existing)
	}
	if resolved, err := filepath.EvalSymlinks(existing); err != nil || resolved != existing {
		return fmt.Errorf("%s root %s does not resolve to itself", name, existing)
	}
	return nil
}

func inspectWorkloadPath(path string, identity WorkloadIdentity, tenantTraverse, allowMissing, privateState bool) error {
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(path, current), current) {
		if part != "" {
			current = filepath.Join(current, part)
		}
		info, err := os.Lstat(current)
		if err != nil {
			if allowMissing && errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return fmt.Errorf("inspect %s: %w", current, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s must be a directory without symlinks", current)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			return fmt.Errorf("cannot inspect owner of %s", current)
		}
		if os.Geteuid() == 0 && owner.Uid != 0 {
			return fmt.Errorf("host path ancestor %s must be root-owned", current)
		}
		permissions := info.Mode().Perm()
		search := permissions & 0001
		write := permissions & 0002
		if owner.Gid == identity.GID {
			search, write = permissions&0010, permissions&0020
		}
		if owner.Uid == identity.UID {
			search, write = permissions&0100, permissions&0200
		}
		if tenantTraverse && search == 0 {
			return fmt.Errorf("workload identity cannot traverse %s", current)
		}
		if privateState && os.Geteuid() == 0 && permissions&0022 != 0 {
			return fmt.Errorf("state path ancestor %s is group- or world-writable", current)
		}
		if identity.UID != uint32(os.Geteuid()) && write != 0 &&
			(privateState || info.Mode()&os.ModeSticky == 0 || owner.Uid != 0) {
			return fmt.Errorf("workload identity can replace host path under %s", current)
		}
	}
	return nil
}

func ensureOwnedDir(path string, uid, gid int, mode os.FileMode) error {
	if err := os.Mkdir(path, mode); err != nil && !errors.Is(err, os.ErrExist) {
		return err
	}
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return fmt.Errorf("%s must be a directory, not a symlink: %w", path, err)
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil {
		return err
	}
	if int(stat.Uid) == uid && int(stat.Gid) == gid && stat.Mode&0o7777 == uint32(mode.Perm()) {
		return nil
	}
	if err := unix.Fchown(fd, os.Geteuid(), gid); err != nil {
		return err
	}
	if err := unix.Fchmod(fd, uint32(mode.Perm())); err != nil {
