func (w WANObservation) Fresh(now time.Time) bool {
	return !w.ObservedAt.IsZero() && !w.ObservedAt.After(now) && now.Sub(w.ObservedAt) <= WANFreshFor
}

func (w WANObservation) Validate() error {
	_, offset := w.ObservedAt.Zone()
	if w.ObservedAt.UnixMilli() <= 0 || offset != 0 || !wanRegionRE.MatchString(w.ReceiverRegion) || len(w.Sources) == 0 || len(w.Sources) > MaxWANRegions {
		return errors.New("invalid WAN observation time or source count")
	}
	seen := make(map[string]bool, len(w.Sources))
	for _, source := range w.Sources {
		if !wanRegionRE.MatchString(source.SourceRegion) || seen[source.SourceRegion] {
			return errors.New("invalid or duplicate WAN source region")
		}
		seen[source.SourceRegion] = true
		for _, value := range []*float64{source.LagGroups, source.StalenessSeconds, source.Members, source.Unregistered, source.Conflicts} {
			if value == nil || !validWANValue(*value) {
				return errors.New("missing or invalid WAN gauge")
			}
		}
		for _, value := range []*float64{source.LagGroups, source.Members, source.Unregistered, source.Conflicts, source.AheadFailuresTotal} {
			if value != nil && (!validWANValue(*value) || math.Trunc(*value) != *value) {
				return errors.New("WAN count must be an exact nonnegative integer")
			}
		}
	}
	return nil
}

func validWANValue(value float64) bool {
	return !math.IsNaN(value) && !math.IsInf(value, 0) && value >= 0 && value <= WANMaxValue
}

// CollectWAN scrapes the native member's unauthenticated loopback admin endpoint.
// The verified host session authenticates delivery onward, not this HTTP scrape.
func CollectWAN(ctx context.Context, env map[string]string) (*WANObservation, error) {
	profile, err := ParseProfile(env)
	if err != nil {
		return nil, err
	}
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(profile.AdminPort)+"/metrics", nil)
	if err != nil {
		return nil, err
	}
	client := &http.Client{Transport: &http.Transport{DisableKeepAlives: true},
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
	observedAt := time.Now().UTC()
	response, err := client.Do(request)
	if err != nil {
		return nil, err
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("WAN metrics HTTP status %d", response.StatusCode)
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, wanBodyBytes+1))
	if err != nil {
		return nil, err
	}
	return ParseWANMetrics(data, env[EnvRegion], observedAt)
}

var wanLabelRE = regexp.MustCompile(`^([a-zA-Z_][a-zA-Z0-9_]*)\s*=\s*("(?:[^"\\\n]|\\[\\"n])*")`)
var wanRegionRE = regexp.MustCompile(`^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$`)

// ParseWANMetrics accepts only the bounded native Prometheus WAN contract.
// A missing gauge, duplicate, unsupported label or invalid value discards the scrape.
func ParseWANMetrics(data []byte, receiverRegion string, observedAt time.Time) (*WANObservation, error) {
	if len(data) > wanBodyBytes {
		return nil, errors.New("WAN metrics exceed size bound")
	}
	sources := make(map[string]*WANSource)
	seen := make(map[string]bool)
	scanner := bufio.NewScanner(bytes.NewReader(data))
	scanner.Buffer(make([]byte, 4096), 16<<10)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		end := strings.IndexAny(line, "{ \t")
		if end < 0 {
			end = len(line)
		}
		metric := line[:end]
		switch metric {
		case "terrabase_wan_lag", "terrabase_wan_staleness_seconds", "terrabase_wan_members",
			"terrabase_wan_unregistered", "terrabase_wan_conflicts", "terrabase_wan_failures_total":
		default:
			continue
		}
		labels, raw, err := parseWANLabels(strings.TrimSpace(line[end:]))
		if err != nil {
			return nil, err
		}
		region, reason := labels["region"], labels["reason"]
		_, hasReason := labels["reason"]
		if !wanRegionRE.MatchString(region) || (metric == "terrabase_wan_failures_total" && !slices.Contains([]string{"heads", "pull", "apply", "ahead"}, reason)) ||
			(metric != "terrabase_wan_failures_total" && hasReason) {
			return nil, errors.New("invalid WAN region or reason label")
		}
		value, err := strconv.ParseFloat(raw, 64)
		if err != nil || !validWANValue(value) || (metric != "terrabase_wan_staleness_seconds" && math.Trunc(value) != value) {
			return nil, errors.New("invalid WAN metric value")
		}
		key := metric + "\x00" + region + "\x00" + reason
		if seen[key] || len(seen) >= MaxWANRegions*9 {
			return nil, errors.New("duplicate or excessive WAN metrics")
		}
		seen[key] = true
		if metric == "terrabase_wan_failures_total" && reason != "ahead" {
			continue
		}
		source := sources[region]
		if source == nil {
			if len(sources) == MaxWANRegions {
				return nil, errors.New("WAN metrics exceed source count bound")
			}
			source = &WANSource{SourceRegion: region}
			sources[region] = source
		}
		switch metric {
		case "terrabase_wan_lag":
			source.LagGroups = new(value)
		case "terrabase_wan_staleness_seconds":
			source.StalenessSeconds = new(value)
		case "terrabase_wan_members":
			source.Members = new(value)
		case "terrabase_wan_unregistered":
			source.Unregistered = new(value)
		case "terrabase_wan_conflicts":
			source.Conflicts = new(value)
		case "terrabase_wan_failures_total":
			source.AheadFailuresTotal = new(value)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if len(sources) == 0 {
		return nil, nil
	}
	observation := &WANObservation{ObservedAt: observedAt, ReceiverRegion: receiverRegion}
	for _, source := range sources {
		observation.Sources = append(observation.Sources, *source)
	}
	slices.SortFunc(observation.Sources, func(a, b WANSource) int { return strings.Compare(a.SourceRegion, b.SourceRegion) })
	if err := observation.Validate(); err != nil {
		return nil, err
	}
	return observation, nil

func (a *Agent) terraBaseRunningReport(ctx context.Context, d Desired) Report {
	// Publication rechecks the cached observation's freshness and exact process while this poll runs.
	// reconcile fenced a member whose data volume is gone before it got
	// here; these checks stop it when the volume goes between the two or
	// while preparation renews the certificate and maintains the mount.
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), err))
	}
	_, _, renewErr := a.prepareTerraBase(ctx, d)
	if stopped, err := a.fenceTerraBaseMember(ctx, d.Role); stopped || err != nil {
		return a.reportFor(d, "failed", errors.Join(errors.New("terrabase data volume is not intact"), renewErr, err))
	}
	// ponytail: a per-node offset of one to seven days keeps the members of
	// a cell that cannot reload from restarting together.
	restartBefore := time.Duration(24+crc32.ChecksumIEEE([]byte(a.cfg.Node))%144) * time.Hour
	member := a.terraBase[d.Role]
	if renewErr == nil && !member.certificateExpiry.IsZero() && time.Until(member.certificateExpiry) < restartBefore {
		served, err := a.terraBaseServedExpiry(ctx, d)
		if err != nil || time.Until(served) < restartBefore {
			stopErr := a.runner.Stop(ctx, d.Role)
			if stopErr == nil {
				delete(a.terraBase, d.Role)
			}
			return a.reportFor(d, "starting", errors.Join(errors.New("restarting to load the renewed member certificate"),
				err, stopErr))
		}
		member.certificateExpiry = served
		a.terraBase[d.Role] = member
	}
	state, healthErr := a.terraBaseState(ctx, d)
	if state == "running" {
		a.collectTerraBaseWAN(ctx, d)
	}
	return a.reportFor(d, state, errors.Join(healthErr, renewErr))
}

func (a *Agent) prepareTerraBase(ctx context.Context, d Desired) (map[string]string, time.Time, error) {
	if len(d.Args) != 0 {
		// The binary lets an argument override the host-owned settings.
		return nil, time.Time{}, errors.New("terrabase members take no arguments")
	}
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return nil, time.Time{}, err
	}
	peer, listed := a.terraBasePeer(profile)
	if !listed {
		return nil, time.Time{}, fmt.Errorf("node %s is not in %s", a.cfg.Node, terrabase.EnvPeers)
	}
	// Recheck the ancestors right before the privileged effects below.
	if err := validateTerraBaseRoot(a.cfg.TerraBaseRoot, a.cfg.InstallRoot, a.cfg.StateRoot, a.cfg.WorkloadIdentity); err != nil {
		return nil, time.Time{}, err
	}
	layout := terrabase.Layout(a.cfg.TerraBaseRoot)
	supervisor, uid, gid := os.Geteuid(), int(a.cfg.WorkloadIdentity.UID), int(a.cfg.WorkloadIdentity.GID)
	// The binary writes its databases and extracted libraries; it only
	// reads its TLS material, which stays supervisor-owned.
	type ownedDir struct {
		path     string
		uid, gid int
		mode     os.FileMode
	}
	dirs := []ownedDir{{string(layout), supervisor, gid, 0o750}, {layout.TLS(), supervisor, gid, 0o750},
		{layout.Bundle(), uid, gid, 0o700}}
	if !a.cfg.TerraBaseDataVolume {
		dirs = append(dirs, ownedDir{layout.Data(), uid, gid, 0o700})
	}
	for _, dir := range dirs {
		if err := ensureOwnedDir(dir.path, dir.uid, dir.gid, dir.mode); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The volume initializer owns a data volume mount; never fall back to
	// the boot disk without one.
	if a.cfg.TerraBaseDataVolume {
		// Artifact and controller requests may have outlasted the caller's
		// fence. Stop any remaining writer before repairing a lost mount.
		if _, err := a.fenceTerraBaseMember(ctx, d.Role); err != nil {
			return nil, time.Time{}, err
		}
		if err := a.ensureTerraBaseDataVolume(ctx); err != nil {
			return nil, time.Time{}, err
		}
	}
	// The member's private key never reaches disk (TS-745).
	if a.cfg.MemoryRuntime {
		if err := vaultsecret.RequireMemoryFilesystem(layout.TLS()); err != nil {
			return nil, time.Time{}, err
		}
	}
	key, err := os.ReadFile(layout.Key())
	if errors.Is(err, os.ErrNotExist) {
		if key, _, err = terrabase.NewMemberKey(); err == nil {
			err = writeOwnedFile(layout.Key(), key, gid)
		}
	}
	if err != nil {
		return nil, time.Time{}, err
	}
	certificate, _ := os.ReadFile(layout.Certificate())
	ca, _ := os.ReadFile(layout.CA())
	if !terrabase.CurrentCertificate(certificate, key, ca, peer, time.Now()) {
		csr, err := terrabase.CertificateRequest(key)
		if err != nil {
			return nil, time.Time{}, err
		}
		var reply terraBasePeerReply
		if err := a.request(ctx, "terrabase-peer", terraBasePeerQuery{CSR: csr}, &reply); err != nil {
			return nil, time.Time{}, err
		}
		if !terrabase.CurrentCertificate(reply.Certificate, key, reply.CA, peer, time.Now()) {
			return nil, time.Time{}, errors.New("controller returned an unusable TerraBase member certificate")
		}
		if err := writeOwnedFile(layout.CA(), reply.CA, gid); err != nil {
			return nil, time.Time{}, err
		}
		if err := writeOwnedFile(layout.Certificate(), reply.Certificate, gid); err != nil {
			return nil, time.Time{}, err
		}
		certificate = reply.Certificate
	}
	return layout.Env(d.Env, profile, peer.Name), terrabase.CertificateExpiry(certificate), nil
}

// terraBasePeer is this host's member in profile: the one named after its

func (a *Agent) terraBaseState(ctx context.Context, d Desired) (string, error) {
	profile, err := terrabase.ParseProfile(d.Env)
	if err != nil {
		return "", err
	}
	if err := terrabase.Healthy(ctx, profile.AdminPort); err != nil {
		return "starting", err
	}
	if profile.ClientPort != 0 {
		peer, _ := a.terraBasePeer(profile)
		layout := terrabase.Layout(a.cfg.TerraBaseRoot)
		ca, err := os.ReadFile(layout.CA())
		if err == nil {
			err = terrabase.Ready(ctx, profile.ClientPort, peer, layout.Certificate(), layout.Key(), ca)
		}
		if err != nil {
			return "starting", err
		}
	}
	return "running", nil
}

func (a *Agent) fenceTerraBaseMember(ctx context.Context, role string) (stopped bool, err error) {
	if !a.cfg.TerraBaseDataVolume || role != terrabase.Role {
		return false, nil
	}
	lost := a.terraBaseDataVolumeIntact()
	if lost == nil {
		return false, nil
	}
	a.terraBaseVolumeConfirmed = ""
	current, observeErr := a.runner.Observe(ctx, role)
	if observeErr == nil && !current.Running {
		return false, nil
	}
	if err := a.runner.Stop(ctx, role); err != nil {
		return false, errors.Join(fmt.Errorf("stop the terrabase member: data volume: %w", lost), observeErr, err)
	}
	delete(a.terraBase, role)
	slog.WarnContext(ctx, "terrabase member stopped: its data volume is not intact", "error", lost)
	return true, nil
}

func Healthy(ctx context.Context, adminPort int) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, "http://127.0.0.1:"+strconv.Itoa(adminPort)+"/healthz", nil)
	if err != nil {
		return err
	}
	response, err := http.DefaultClient.Do(request)
	if err != nil {
		return fmt.Errorf("terrabase health: %w", err)
	}
	defer response.Body.Close()
	var body struct {
		Status string `json:"status"`
	}
	data, err := io.ReadAll(io.LimitReader(response.Body, 4096))
	if err == nil && response.StatusCode == http.StatusOK {
		err = json.Unmarshal(data, &body)
	}
	if err != nil || response.StatusCode != http.StatusOK || body.Status != "ok" {
		return fmt.Errorf("terrabase health: HTTP %d %q", response.StatusCode, strings.TrimSpace(string(data)))
	}
	return nil
}

func testNATSUserKey(node string) string {
	seed := sha256.Sum256([]byte("host-test-user:" + node))
	pair, err := nkeys.FromRawSeed(nkeys.PrefixByteUser, seed[:])
	if err != nil {
		panic(err)
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil {
		panic(err)
	}
	return public
}

func signRequest(r *request, key ed25519.PrivateKey, cell string) error {
	if len(key) != ed25519.PrivateKeySize {
		return errors.New("invalid host identity key")
	}
	payload, err := json.Marshal(r)
	if err != nil {
		return err
	}
	r.Envelope, err = protocol.SignEnvelope(payload, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, r.IssuedAt, r.IssuedAt.Add(requestTTL), key)
	return err
}

func verifyRequest(r request, key ed25519.PublicKey, cell string, now time.Time) error {
	if r.Version != 1 || !lowerHex(r.Nonce, 32) || !entityid.Valid(r.SessionID) || r.IssuedAt.IsZero() || r.IssuedAt.After(now.Add(maxClockSkew)) || now.Sub(r.IssuedAt) >= requestTTL {
		return errors.New("invalid or expired host request")
	}
	if !r.Envelope.IssuedAt.Equal(r.IssuedAt) || r.Envelope.Epoch != r.Epoch {
		return errors.New("host request envelope binding mismatch")
	}
	return protocol.VerifyEnvelope(r.Envelope, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, key, now, protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew})
}

func decodeStrict(data []byte, destination any) error {
	return protocol.DecodeStrict(data, destination, 512<<10)
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

func SignEnvelope(
	payload []byte,
	scope EnvelopeScope,
	issuedAt time.Time,
	expiresAt time.Time,
	privateKey ed25519.PrivateKey,
) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: expected an Ed25519 private key", ErrInvalidEnvelope)
	}
	normalized, err := normalizeScope(scope)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validProtocolTime(issuedAt) || !validProtocolTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: issuedAt and expiresAt must form a valid UTC interval", ErrInvalidEnvelope)
	}
	compactPayload, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: EnvelopeSchemaVersion,
		Region:        normalized.Region,
		Kind:          normalized.Kind,
		Actor:         normalized.Actor,
		Generation:    normalized.Generation,
		Epoch:         normalized.Epoch,
		OperationID:   normalized.OperationID,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		KeyID:         keyID,
		Payload:       compactPayload,
	}
	material, err := signedMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// VerifyEnvelope verifies signature, exact semantic scope, expiry, and fencing
// metadata. Replay prevention for OperationID belongs to the durable consumer.
func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func exchange(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey, r request, out any) error {
	return exchangeWithEnvelope(ctx, conn, cell, controllerKey, r, out, nil)
}

func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

