const (
	SchemaVersion      = 1
	MetadataKey        = "terrascale_hostboot_v1"
	MaxDescriptorBytes = 4096
	// EnrollmentMetadataKey carries the exact public host enrollment bundle.
	// Controllers deliver it at launch so the host image stays deployment-neutral.
	EnrollmentMetadataKey = "terrascale-host-enrollment-v1"
	// NodePoolMetadataKey marks an instance pool's instance; its value is {"schemaVersion":1}.
	NodePoolMetadataKey = "terrascale-node-pool"
)

var (
	ErrInvalidDescriptor = errors.New("managed host boot descriptor is invalid")
	descriptorToken      = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)
	descriptorDigest     = regexp.MustCompile(`^[0-9a-f]{64}$`)
	descriptorImageID    = regexp.MustCompile(`^ocid1\.image\.[A-Za-z0-9][A-Za-z0-9._-]{0,242}$`)
)

// Descriptor is a strict public hint for one managed-host launch. OCI values
// are supplied by the region-pinned Fleet and placement values by its durable
// member record. Instance identity is not known until after launch.
//
// A static descriptor (schema 2, see Static) names only the cell, region and
// node of an operator-launched C# TerraBase host. Its managed members are
// zero and omitted, so a schema-1 descriptor keeps its exact bytes.
type Descriptor struct {
	SchemaVersion            int    `json:"schema_version"`
	Cell                     string `json:"cell"`
	Region                   string `json:"region"`
	Node                     string `json:"node"`
	Owner                    string `json:"owner,omitzero"`
	FleetGeneration          uint64 `json:"fleet_generation,omitzero"`
	CreateKey                string `json:"create_key,omitzero"`
	ImageID                  string `json:"image_id,omitzero"`
	DatabaseID               string `json:"database_id,omitzero"`
	PartitionID              string `json:"partition_id,omitzero"`
	SeatID                   string `json:"seat_id,omitzero"`
	HostAttempt              uint64 `json:"host_attempt,omitzero"`
	IntentGeneration         uint64 `json:"intent_generation,omitzero"`
	IntentPayloadDigest      string `json:"intent_payload_digest,omitzero"`
	CanonicalRosterDigest    string `json:"canonical_roster_digest,omitzero"`
	ManagedHostProfileDigest string `json:"managed_host_profile_digest,omitzero"`
	RuntimeManifestDigest    string `json:"runtime_manifest_digest,omitzero"`
}

// StaticSchemaVersion is the schema of a static C# TerraBase host descriptor.
const StaticSchemaVersion = 2

// Static is the descriptor of an operator-launched C# TerraBase host node
// (a <cell>-db-<n> server name), of the host agent on a controller VM
// (<cell>-ctl-<n>, or the region's node ts-<region>-<n>, which runs the
// controller), or of a node pool's host (<cell>-pool-<pool>-<n>) in a cell. It grants nothing by itself: the controller
// enrolls a TerraBase host only when its signed profile lists node at the
// host's private address, and a controller host only from a controller's
// private address; OCI must show that instance either way.
func Static(cell, region, node string) Descriptor {
	return Descriptor{SchemaVersion: StaticSchemaVersion, Cell: cell, Region: region, Node: node}
}

// IsStatic reports whether the descriptor names a static host.
func (descriptor Descriptor) IsStatic() bool { return descriptor.SchemaVersion == StaticSchemaVersion }

// IsController reports whether a static descriptor names a controller VM.
func (descriptor Descriptor) IsController() bool {
	cell, err := naming.RegionCell(descriptor.Region).Name()
	return descriptor.IsStatic() && err == nil && (strings.HasPrefix(descriptor.Node, cell+"-"+naming.Controller+"-") ||
		strings.HasPrefix(descriptor.Node, regionNode(descriptor.Region)))
}

// regionNode is the prefix of the region's node names, e.g. ts-sfo-.
func regionNode(region string) string { return "ts-" + strings.ToLower(region) + "-" }

// Validate checks the closed v1 identity and digest bindings and the bounded
// canonical wire size. It performs no signature or live-resource checks.
func (descriptor Descriptor) Validate() error {
	_, err := descriptor.CanonicalBytes()
	return err
}

// CanonicalBytes returns the deterministic v1 JSON representation used in OCI
// instance metadata and retry binding.
func (descriptor Descriptor) CanonicalBytes() ([]byte, error) {
	if err := descriptor.validateFields(); err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(descriptor)
	if err != nil {
		return nil, fmt.Errorf("%w: encode canonical JSON: %v", ErrInvalidDescriptor, err)
	}
	if len(wire) == 0 || len(wire) > MaxDescriptorBytes {
		return nil, fmt.Errorf("%w: canonical JSON exceeds %d bytes", ErrInvalidDescriptor, MaxDescriptorBytes)
	}
	return wire, nil
}

// Digest returns the lowercase SHA-256 digest of CanonicalBytes.
func (descriptor Descriptor) Digest() (string, error) {
	wire, err := descriptor.CanonicalBytes()
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(wire)
	return hex.EncodeToString(digest[:]), nil
}

// Parse decodes one exact canonical v1 managed descriptor. Unknown members,
// duplicate names, oversized input, and alternate noncanonical encodings are
// rejected, and so is a static descriptor.
func Parse(wire []byte) (Descriptor, error) {
	descriptor, err := ParseHost(wire)
	if err == nil && descriptor.IsStatic() {
		return Descriptor{}, fmt.Errorf("%w: a static host is not a managed launch", ErrInvalidDescriptor)
	}
	return descriptor, err
}

// ParseHost decodes one exact canonical managed or static descriptor.
func ParseHost(wire []byte) (Descriptor, error) {
	if len(wire) == 0 || len(wire) > MaxDescriptorBytes {
		return Descriptor{}, fmt.Errorf("%w: wire is absent or exceeds %d bytes", ErrInvalidDescriptor, MaxDescriptorBytes)
	}
	var descriptor Descriptor
	if err := protocol.DecodeStrict(wire, &descriptor, MaxDescriptorBytes); err != nil {
		return Descriptor{}, fmt.Errorf("%w: decode strict JSON: %v", ErrInvalidDescriptor, err)
	}
	canonical, err := descriptor.CanonicalBytes()
	if err != nil {
		return Descriptor{}, err
	}
	if !bytes.Equal(wire, canonical) {
		return Descriptor{}, fmt.Errorf("%w: wire is not the exact canonical representation", ErrInvalidDescriptor)
	}
	return descriptor, nil
}

func (descriptor Descriptor) validateFields() error {
	if descriptor.IsStatic() {
		cell, err := naming.RegionCell(descriptor.Region).Name()
		number, ok := strings.CutPrefix(descriptor.Node, cell+"-"+naming.Member+"-")
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, cell+"-"+naming.Controller+"-")
		}
		if !ok {
			number, ok = strings.CutPrefix(descriptor.Node, regionNode(descriptor.Region))
		}
		if pool, isPool := strings.CutPrefix(descriptor.Node, cell+"-pool-"); !ok && isPool {
			// The scheme allows no hyphen in a pool name.
			_, number, ok = strings.Cut(pool, "-")
		}
		if err != nil || !validCellRegion(descriptor.Cell, descriptor.Region) || !ok ||
			naming.Validate(descriptor.Node) != nil || strings.Contains(number, "-") ||
			descriptor != Static(descriptor.Cell, descriptor.Region, descriptor.Node) {
			return fmt.Errorf("%w: static host must name one database, controller, node or pool server of its cell and nothing else", ErrInvalidDescriptor)
		}
		return nil
	}
	if descriptor.SchemaVersion != SchemaVersion || !validCellRegion(descriptor.Cell, descriptor.Region) ||
		!descriptorToken.MatchString(descriptor.Node) || !descriptorToken.MatchString(descriptor.Owner) ||
		!validCreateKey(descriptor.CreateKey) || !descriptorImageID.MatchString(descriptor.ImageID) ||
		descriptor.FleetGeneration == 0 || descriptor.HostAttempt == 0 || descriptor.IntentGeneration == 0 ||
		!entityid.Valid(descriptor.DatabaseID) || !entityid.Valid(descriptor.PartitionID) ||
		!entityid.Valid(descriptor.SeatID) ||
		!descriptorDigest.MatchString(descriptor.IntentPayloadDigest) ||
		!descriptorDigest.MatchString(descriptor.CanonicalRosterDigest) ||
		!descriptorDigest.MatchString(descriptor.ManagedHostProfileDigest) ||
		!descriptorDigest.MatchString(descriptor.RuntimeManifestDigest) {
		return fmt.Errorf("%w: required identity, generation, image, or digest binding", ErrInvalidDescriptor)
	}
	return nil
}

func validCellRegion(cell, region string) bool {
	return catalog.MatchesName(cell, region)
}

func validCreateKey(value string) bool {
	return entityid.Valid(value)
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

const terminalTestDigest = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"

func terminalTestStore(t *testing.T) *GrantStore {
	t.Helper()

	broker, err := server.NewServer(&server.Options{
		Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir(),
